const fillP = (k, v) => ((v - C[k].min) / (C[k].max - C[k].min) * 100).toFixed(1) + "%";
function ctl(k, v, label, hint) { const c = C[k]; return `<div class="ctl"><div class="l"><label for="c_${k}">${label || c.l}</label><output id="o_${k}">${c.f(v)}</output></div><input type="range" id="c_${k}" data-k="${k}" min="${c.min}" max="${c.max}" step="${c.step}" value="${v}" style="--p:${fillP(k, v)}">${hint !== false && c.h ? `<small>${c.h}</small>` : ""}</div>`; }
